ComDiff::ComDiff()
{
    try
    {
        // Initialize the NX Open C++ API environment
        ComDiff::theSession = NXOpen::Session::GetSession();
        ComDiff::theUI = UI::GetUI();
        theDlxFileName = "ComDiff.dlx";
        theDialog = ComDiff::theUI->CreateDialog(theDlxFileName);
        // Registration of callback functions
        theDialog->AddApplyHandler(make_callback(this, &ComDiff::apply_cb));
        theDialog->AddOkHandler(make_callback(this, &ComDiff::ok_cb));
        theDialog->AddUpdateHandler(make_callback(this, &ComDiff::update_cb));
        theDialog->AddInitializeHandler(make_callback(this, &ComDiff::initialize_cb));
        theDialog->AddDialogShownHandler(make_callback(this, &ComDiff::dialogShown_cb));
        selectedFit.clear();
        hasComputedResult = false;
        currentFitResult.hole.upper = 0.0;
        currentFitResult.hole.lower = 0.0;
        currentFitResult.shaft.upper = 0.0;
        currentFitResult.shaft.lower = 0.0;
        selectedDimension = NULL;
        selectedSize = 0.0;
        hasSelectedDimension = false;
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        throw;
    }
}

