void ComDiff::disableNonSelectableButtons()
{
    for (size_t i = 0; i < sizeof(kDisabledButtonIds) / sizeof(kDisabledButtonIds[0]); ++i)
    {
        PropertyList* props = GetBlockProperties(kDisabledButtonIds[i]);
        props->SetLogical("Enable", false);
        delete props;
    }
}

void ComDiff::setToggleValue(const char* blockId, bool value)
{
    PropertyList* props = GetBlockProperties(blockId);
    props->SetLogical("Value", value);
    delete props;
}

bool ComDiff::getToggleValue(const char* blockId)
{
    PropertyList* props = GetBlockProperties(blockId);
    const bool value = props->GetLogical("Value");
    delete props;
    return value;
}

void ComDiff::setStringValue(const char* blockId, const std::string& value)
{
    PropertyList* props = GetBlockProperties(blockId);
    props->SetString("Value", value.c_str());
    delete props;
}

void ComDiff::setDoubleValue(const char* blockId, double value)
{
    PropertyList* props = GetBlockProperties(blockId);
    props->SetDouble("Value", value);
    delete props;
}

void ComDiff::clearResultBlocks()
{
    setStringValue("kong", "");
    setStringValue("zhou", "");
    setDoubleValue("max", 0.0);
    setDoubleValue("min", 0.0);
    setDoubleValue("spck", 0.0);
    setDoubleValue("spcz", 0.0);
    setDoubleValue("xpck", 0.0);
    setDoubleValue("xpcz", 0.0);
    hasComputedResult = false;
}

void ComDiff::promptAndCacheDimension()
{
    Part* workPart = theSession->Parts()->Work();
    if (workPart == NULL)
    {
        throw std::runtime_error("当前没有工作部件");
    }

    selectedDimension = SelectLinearDimension(theUI);
    selectedSize = GetDimensionValue(workPart, selectedDimension);
    hasSelectedDimension = true;
}

void ComDiff::setSelectedFit(const std::string& fit)
{
    selectedFit = fit;
    setStringValue("kong", HoleToken(fit));
    setStringValue("zhou", ShaftToken(fit));
    setDoubleValue("max", 0.0);
    setDoubleValue("min", 0.0);
    setDoubleValue("spck", 0.0);
    setDoubleValue("spcz", 0.0);
    setDoubleValue("xpck", 0.0);
    setDoubleValue("xpcz", 0.0);
    hasComputedResult = false;

    if (hasSelectedDimension)
    {
        refreshResultBySelectedFit();
    }
}

bool ComDiff::handleFitButtonClicked(NXOpen::BlockStyler::UIBlock* block)
{
    if (block == NULL)
    {
        return false;
    }

    PropertyList* props = block->GetProperties();
    const NXString blockIdNx = props->GetString("BlockID");
    const std::string blockId = blockIdNx.GetText();
    delete props;

    const std::string fit = NormalizeFitFromBlockId(blockId);
    if (fit.empty() || fit.find('/') == std::string::npos)
    {
        return false;
    }

    setSelectedFit(fit);
    return true;
}

void ComDiff::refreshResultBySelectedFit()
{
    if (selectedFit.empty())
    {
        throw std::runtime_error("请先选择配合方式");
    }

    if (!hasSelectedDimension)
    {
        throw std::runtime_error("请先选择尺寸");
    }

    currentFitResult = ComputeFit(selectedSize, selectedFit);
    hasComputedResult = true;

    setStringValue("kong", HoleToken(selectedFit));
    setStringValue("zhou", ShaftToken(selectedFit));
    setDoubleValue("max", (currentFitResult.hole.upper - currentFitResult.shaft.lower) / 1000.0);
    setDoubleValue("min", (currentFitResult.hole.lower - currentFitResult.shaft.upper) / 1000.0);
    setDoubleValue("spck", currentFitResult.hole.upper / 1000.0);
    setDoubleValue("spcz", currentFitResult.shaft.upper / 1000.0);
    setDoubleValue("xpck", currentFitResult.hole.lower / 1000.0);
    setDoubleValue("xpcz", currentFitResult.shaft.lower / 1000.0);
}

void ComDiff::applySelectedFitToDimension()
{
    if (selectedFit.empty())
    {
        throw std::runtime_error("请先选择配合方式");
    }

    if (!hasSelectedDimension || selectedDimension == NULL)
    {
        throw std::runtime_error("请先选择尺寸");
    }

    if (!getToggleValue("k1") && !getToggleValue("z1"))
    {
        throw std::runtime_error("请在“标注孔”和“标注轴”中二选一");
    }

    UF_initialize();

    try
    {
        Part* workPart = theSession->Parts()->Work();
        if (workPart == NULL)
        {
            throw std::runtime_error("当前没有工作部件");
        }

        refreshResultBySelectedFit();

        const bool annotateHole = getToggleValue("k1");
        const Deviation deviation = annotateHole ? currentFitResult.hole : currentFitResult.shaft;
        ApplyDeviationToDimension(workPart, selectedDimension, deviation);
    }
    catch (...)
    {
        UF_terminate();
        throw;
    }

    UF_terminate();
}

//------------------------------------------------------------------------------
//Callback Name: dialogShown_cb
//This callback is executed just before the dialog launch. Thus any value set 
//here will take precedence and dialog will be launched showing that value. 
//------------------------------------------------------------------------------
void ComDiff::dialogShown_cb()
{
    try
    {
        disableNonSelectableButtons();
        setToggleValue("k1", true);
        setToggleValue("z1", false);
        clearResultBlocks();
        promptAndCacheDimension();
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        ComDiff::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
}

//------------------------------------------------------------------------------
//Callback Name: apply_cb
//------------------------------------------------------------------------------
int ComDiff::apply_cb()
{
    int errorCode = 0;
    try
    {
        applySelectedFitToDimension();
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        ComDiff::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

//------------------------------------------------------------------------------
//Callback Name: update_cb
//------------------------------------------------------------------------------
int ComDiff::update_cb(NXOpen::BlockStyler::UIBlock* block)
{
    try
    {
        if (block == k1)
        {
            if (getToggleValue("k1"))
            {
                setToggleValue("z1", false);
            }
            else if (!getToggleValue("z1"))
            {
                setToggleValue("k1", true);
            }
        }
        else if (block == z1)
        {
            if (getToggleValue("z1"))
            {
                setToggleValue("k1", false);
            }
            else if (!getToggleValue("k1"))
            {
                setToggleValue("z1", true);
            }
        }
        else
        {
            handleFitButtonClicked(block);
        }
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        ComDiff::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return 0;
}

//------------------------------------------------------------------------------
//Callback Name: ok_cb
//------------------------------------------------------------------------------
int ComDiff::ok_cb()
{
    int errorCode = 0;
    try
    {
        errorCode = apply_cb();
    }
    catch(exception& ex)
    {
        //---- Enter your exception handling code here -----
        errorCode = 1;
        ComDiff::theUI->NXMessageBox()->Show("Block Styler", NXOpen::NXMessageBox::DialogTypeError, ex.what());
    }
    return errorCode;
}

//------------------------------------------------------------------------------
//Function Name: GetBlockProperties
//Description: Returns the propertylist of the specified BlockID
//------------------------------------------------------------------------------
PropertyList* ComDiff::GetBlockProperties(const char *blockID)
{
    return theDialog->GetBlockProperties(blockID);
}
